import{_ as r,o as t,c as e,a2 as s}from"./chunks/framework.B2QVIpOM.js";const h=JSON.parse('{"title":"神托会培基书院 · 2022/23资料年份 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-164c0b8a","school_zh":"神托会培基书院","school_en":"—","grade":"s1","year":"2022-23","year_label":"2022/23资料年份","type":"interview","title":"神托会培基书院 · 2022/23资料年份 · 中一 · 面试","anonymous":true,"source_ids":["C2223-SPKC-FIRST","C2223-SPKC-SECOND"],"rounds":["r1","r2"]},"headers":[],"relativePath":"reports/school-164c0b8a/s1/2022-23-interview.md","filePath":"reports/school-164c0b8a/s1/2022-23-interview.md"}'),p={name:"reports/school-164c0b8a/s1/2022-23-interview.md"};function n(a,o,c,l,g,i){return t(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="神托会培基书院-·-2022-23资料年份-·-中一-·-面试" tabindex="-1">神托会培基书院 · 2022/23资料年份 · 中一 · 面试 <a class="header-anchor" href="#神托会培基书院-·-2022-23资料年份-·-中一-·-面试" aria-label="Permalink to &quot;神托会培基书院 · 2022/23资料年份 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-164c0b8a">← 返回神托会培基书院资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c2223-spkc-first" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-spkc-first" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-spkc-first}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong> 英语</p><p><strong>网上面见后提交短片</strong></p><p>Zoom一对一面试，核对身份证明后朗读、回答问题，老师再说明视频任务；须在面试结束后30分钟内拍摄并上传。影片长度多记为1分半至2分钟，也有1至2分钟版本。某次从核对证件至Zoom结束不足15分钟。</p><p><strong>自我介绍差异</strong></p><p>有一份先作自我介绍，另有学生明确表示没有要求介绍；结束前可能让学生向老师提问。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>诗歌与追问</strong></p><p>朗读诗歌或文章，再答约2至6题，老师会按答案追问。一组诗歌围绕愚人节恶作剧：学生把发声坐垫、假虫、糖果虫、塑料道具或金鱼放进课堂，最后被留堂。题目包括故事地点及判断依据、押韵词、糖果虫的味道和质感、是否应庆祝愚人节、恶作剧后留堂是否合理及其他处理建议。</p><p><strong>另一篇诗歌</strong></p><p>另有两个壶或罐子形状不同的诗歌：一个高而窄口，一个矮胖；根据内容回答问题。其他版本问哪个词语描写太阳炽热。</p></blockquote><blockquote><p><strong>视频任务：</strong> 英语</p><p><strong>白雪公主改编</strong></p><p>用刚读诗歌中的三个指定物件，为《白雪公主》创作并演出新结局。不同回忆的组合包括金鱼、虫、坐垫，或金鱼、坐垫、苹果；须按自己获派组合完成。</p><p><strong>角色推销与其他版本</strong></p><p>装扮成一种壶或罐子，向顾客说明如何服务、为何优于其他款式及为何值得购买；或以马戏团主人身份，设计新动物的表演。另有拍摄烹饪过程、介绍令自己快乐的物品等版本。</p></blockquote><h2 id="record-c2223-spkc-second" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-spkc-second" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-spkc-second}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong> 英语及粤语</p><p><strong>校长及教师主持小组面试</strong></p><p>多份网上次轮反馈由校长、副校长或老师主持。部分记录等候约15分钟、正式面试约15分钟，另有全程约一小时的回忆；等待与答题时间不能混为一谈。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>居家物品展示</strong></p><p>按指定条件从家中找一件物品并介绍，要求可能是最有趣、重要、不寻常、令人惊叹、能装饰家居，或在不开心时给予鼓励；部分学生需要尽快找出并举手分享。</p><p><strong>个人联想与问答</strong></p><p>用食物、动物或一种文具形容自己并说明相似处；用一个形容词描述性格；介绍最不喜欢的书并解释。有老师在交流中表示欣赏积极参与的学生。</p></blockquote><blockquote><p><strong>语文与协作：</strong> 粤语</p><p><strong>发问还原句子</strong></p><p>老师给出缺失若干词语的句子，学生透过提问和组内讨论猜回内容。例如“今天是（日子），我和（人物）去（活动），买了（形容词）（物件）”；另一个版本只给“传出……原来……”等连接部分，并用名词、动词、形容词作提示。</p><p><strong>问答规则的不同版本</strong></p><p>有版本允许一分钟内自由发问，老师只答是或否，随后组员讨论一分钟，再补问一题；另有每人只能提出一题的版本。也有讨论或辩论一件事情的回忆。</p></blockquote><blockquote><p><strong>结束环节：</strong> 语言未注明</p><p><strong>提问与问卷</strong></p><p>部分场次留有向学校提问的机会；面试后填写对学校、活动感受及期望的问卷。</p></blockquote>',20)])])}const u=r(p,[["render",n]]);export{h as __pageData,u as default};
